mapper.select:
select a.alliance_id as allianceId, a.tenant_id as tenantId, a.alliance_name as allianceName, a.owner_member_id as ownerMemberId, a.alliance_status as allianceStatus, a.create_time as createTime, count(am.id) as memberCount, coalesce(nullif(owner.nickname, ''), nullif(owner.legal_subject_name, ''), owner.member_code) as ownerMerchantName from ry_rental.ry_rental_alliance a left join ry_rental.ry_rental_alliance_member am on am.alliance_id = a.alliance_id and am.tenant_id = a.tenant_id and am.member_status = 1 and am.is_delete = 0 left join ry_rental.ry_rental_member owner on owner.member_id = a.owner_member_id and owner.tenant_id = a.tenant_id and owner.is_delete = 0 where a.is_delete = 0 and a.alliance_status = #{status}
and (a.alliance_name like concat('%', #{keyword}, '%') or owner.nickname like concat('%', #{keyword}, '%') or owner.legal_subject_name like concat('%', #{keyword}, '%') or owner.member_code like concat('%', #{keyword}, '%'))
group by a.alliance_id, a.tenant_id, a.alliance_name, a.owner_member_id, a.alliance_status, a.create_time, owner.nickname, owner.legal_subject_name, owner.member_code order by a.create_time desc, a.alliance_id desc

select exists(select 1 from ry_rental.ry_rental_alliance_order_slot
  where tenant_id = #{tenantId} and member_id = #{memberId}
    and alliance_order_id = #{allianceOrderId} and slot_status = 1 and is_delete = 0)
